:return: float. The total number of seconds in the given timedelta object.
"""
try:
    # Python 2.7
    return td.total_seconds()
except AttributeError:
    # Python 2.6
    return (td.microseconds + (td.seconds + td.days * 24 * 3600) * 10**6) / 10**6

