elif match.re.pattern == r"[^0-9]":
    return base_characters['0'] + base_characters['9'] - base_characters['0']

elif match.re.pattern == r"[^\s]":
    return base_characters['z'] - base_characters['0'] - base_characters['9'] - base_characters['A'] - base_characters['Z']

elif match.re.pattern == r"[\s]":
    return base_characters['0'] + base_characters['9'] + base_characters['A'] + base_characters['Z']

else:
    return base_characters['z'] * base_characters['z']

"""This function yields lists of directories to search for the history log in. It first checks if logs should be read, and then iterates over unique log directories obtained from the hadoop log directories. If the directory exists, it logs an info message: 'Looking for history log in {directory}...'. It then yields a list containing the directory.

:param self: HadoopJobRunner. An instance of the HadoopJobRunner class.
:param output_dir: str. The output directory to search for the history log. Defaults to None.
:return: Generator. Yields lists of directories to search for the history log in.
"""
if _read_logs(self):
    log_dirs = []
    if self._opts['jobconf'].get('mapreduce.job.dir', None):
        log_dirs.append(self._opts['jobconf'].get('mapreduce.job.dir'))
    if self._opts['jobconf'].get('mapreduce.jobtracker.jobhistory.done-dir', None):
        log_dirs.append(self._opts['jobconf'].get('mapreduce.jobtracker.jobhistory.done-dir'))
    if self._opts['jobconf'].get('mapreduce.jobtracker.jobhistory.location', None):
        log_dirs.append(self._opts['jobconf'].get('mapreduce.jobtracker.jobhistory.location'))
    if output_dir:
        log_dirs.append(output_dir)
    log_dirs = [log_dir for log_dir in log_dirs if log_dir]
    log_dirs = unique(log_dirs)
    for log_dir in log_dirs:
        log.info('Looking for history log in %s...' % log_dir)
        yield [log_dir]

