    raise exception.InvalidParameterValue("The type of the record does not support weighted or latency-based")
if type == "SRV" and identifier != ("",):
    raise exception.InvalidParameterValue("The type of the record does not support weighted or latency-based.")
if type == "MX" and identifier != ("",):
    raise exception.InvalidParameterValue("The type of the record does not support geolocation routing.")
if type == "NS" and identifier != ("",):
    raise exception.InvalidParameterValue("The type of the record does not support geolocation routing.")
records = self.find_records_by_name(name, type, identifier)
if len(records) == 0:
