"""This function creates a patch object that contains only the changes between the original and modified resources. It compares the values of each key in the original and modified dictionaries and constructs a patch object with the differences.

:param original: object. The original deserialized resource.
:param modified: object. The modified deserialized resource.
:return: object. An object that contains only the changes from the original to modified resources, suitable for passing to a PATCH method.
"""
patch = {}
for key in modified:
    if key in original:
        if isinstance(original[key], dict):
            if original[key] != modified[key]:
                patch[key] = makepatch(original[key], modified[key])
        elif isinstance(original[key], list):
            if original[key] != modified[key]:
                patch[key] = modified[key]
        else:
            if original[key] != modified[key]:
                patch[key] = modified[key]
    else:
        patch[key] = modified[key]
return patch

"""This function takes a URL as input and parses it. It then convert the parsed result into a dictionary using the parsed result and unquote password which determines whether the password in the URL should be unquoted or not.

:param url: String. The URL to be parsed.
:param unquote_password: Bool. Whether to unquote the password in the URL. Defaults to False.
:return: Dictionary. The parsed URL as a dictionary.
"""
if not isinstance(url, str):
    raise ValueError('Invalid database URL: "{0}".'.format(url))

pattern = re.compile(
    r'^(?:(?P<scheme>[a-z][a-z0-9]+)://)?'
    r'(?:(?P<user>[^/?#]+)?'
    r'(?::(?P<password>[^/?#]+))?'
    r')?@(?:(?P<host>[^\[\]:/?#]+)|'
    r'\[(?P<ipv6host>[^/?#]+)\])?'
    r'(?::(?P<port>[0-9]+))?'
    r'(?:/(?P<database>[^/?#]+))?'
    r'(?:\?(?P<options>.+))?'
    r'$'
)
m = pattern.match(url)
if m is None:
    raise ValueError('Invalid database URL: "{0}".'.format(url))

components = m.groupdict()

if components['scheme'] is not None:
    components['scheme'] = components['scheme'].lower()

if components['user'] is not None:
    components['user'] = unquote(components['user'])

if components['password'] is not None:
    if unquote_password:
        components['password'] = unquote(components['password'])
    else:
        components['password'] = components['password']

if components['host'] is not None:
    components['host'] = unquote(components['host'])

if components['ipv6host'] is not None:
    components['host'] = components['ipv6host']
    del components['ipv6host']

if components['port'] is not None:
    components['port'] = int(components['port'])

if components['database'] is not None:
    components['database'] = unquote(components['database'])

if components['options'] is not None:
    options = {}
    for pair in components['options'].split('&'):
        k, v = pair.split('=')
        k = unquote(k)
        v = unquote(v)
        options[k] = v
    components['options'] = options
else:
    components['options'] = {}

return comp

