:param self: IntentDefBuilder. An instance of the IntentDefBuilder class.
:return: IntentDefinition. The created concrete instance of IntentDefinition.
"""
if self._name is None:
    raise SyntaxError(
        "Tried to create an intent without specifying its name."
    )
if self._modifiers_repr is None:
    raise SyntaxError(
        "Tried to create an intent without specifying its modifiers."
    )
if self._nb_training_ex_asked is None:
    raise SyntaxError(
        "Tried to create an intent without specifying the number of training examples."
    )
if self._nb_testing_ex_asked is None:
    raise SyntaxError(
        "Tried to create an intent without specifying the number of testing examples."
    )

if self._variation_name is not None:
    try:
        return AST.get_or_create()._intent_definitions[self._name][
            self._variation_name
        ]
    except KeyError:
        raise KeyError(
            "Tried to create an intent variation '"
            + self._variation_name
            + "' for intent '"
            + self._name
            + "', but this variation was not declared."
        )

return IntentDefinition(
    self._name,
    self._modifiers_repr,
    self._nb_training_ex_asked,
    self._nb_testing_ex_asked,
)

