"""This function receives data from the socket until the connection is closed, up to a specified maximum size. If more than the maximum size is received, it raises a `MessageTooLong` exception.


:param self: BufferedSocket, an instance of the BufferedSocket class.
:param timeout: int. The timeout value for receiving data. Defaults to `_UNSET` if not specified.
:param maxsize: int. The maximum size of received data. Defaults to `_UNSET` if not specified.
:return: bytes. The received data up to the maximum size specified.

"""
if timeout is _UNSET:
    timeout = self.timeout
if maxsize is _UNSET:
    maxsize = self.maxsize
if timeout is None:
    timeout = None
else:
    timeout = self.timeout
buf = self._read_buffer
rbufsize = self._rbufsize
# try to enable TCP_QUICKACK
try:
    self.ioctl(socket.SIO_FLUSHIO, 0)
except socket.error:
    pass
flags = self.flags
if not buf:
    buf = bytearray(max(self.blocksize, maxsize))
    if rbufsize is None:
        rbufsize = min(buf if isinstance(buf, int) else len(buf), 65536)
self._rbuf = buf
self._rbufsize = rbufsize
self._size = 0
self._flags = flags
if timeout is not None:
    end = time.time() + timeout
while True:
    try:
        data = self._sock.recv_into(buf)
    except socket.timeout:
        break
    except socket.error:
        if self._flags & socket.MSG_OOB:
            break
        raise
    if not data:
        break
    n = len(data)
    if maxsize is not None and maxsize >= 0:
        if self._size + n > maxsize:
            raise MessageTooLong("Message too long")
    if timeout is not None:
        timeout = end - time.time()
        if timeout < 0:
            break
    with self._read_lock:
        self._size += n
        self._write_buffer += data
return bytes(self._read_buffer)

