    if summary[col]["type"] == Variable.TYPE_NUM
]
cat_columns = [
    col
    for col in summary.keys()
    if summary[col]["type"] == Variable.TYPE_CAT
]

# If there are no numerical or categorical columns, return None
if len(num_columns) == 0 and len(cat_columns) == 0:
    return None

# If there are only numerical columns, discretize the DataFrame using a uniform discretization method
if len(cat_columns) == 0:
    df_discretized = discretize_dataframe(
        Discretizer(
            DiscretizationType.UNIFORM,
            n_bins=config.categorical_maximum_correlation_distinct,
            reset_index=False,
        ),
        df,
    )
# If there are only categorical columns, do not discretize the DataFrame
elif len(num_columns) == 0:
    df_discretized = df
# If there are both numerical and categorical columns, discretize the DataFrame using a uniform discretization method
else:
    df_discretized = discretize_dataframe(
        Discretizer(
            DiscretizationType.UNIFFORM,
            n_bins=config.categorical_maximum_correlation_distinct,
            reset_index=False,  # TODO: check if this is correct
        ),
        df,
    )

# Calculate the correlation scores between each pair of columns using either the pairwise Spearman correlation or the pairwise Cramers' V, depending on the column type
correlations = {}
for col1 in df_discretized.columns:
    for col2 in df_discretized.columns:
        if col1 == col2:
            continue
        if col1 in num_columns and col2 in num_columns:
            correlations[(col1, col2)] = df_discretized[col1].corr(
                df_discretized[col2]
            )
        elif col1 in cat_columns and col2 in cat_columns:
            correlations[(col1, col2)] = cramers_v(
                df_discretized[col1], df_discretized[col2]
            )

# Return the correlation matrix
return pd.DataFrame(correlations, index=df_discretized.columns).fillna(0)

"""This function returns a string representation of the Table object. If the Table object has headers, it includes the headers and data in the string: '{type name}(headers={headers!r}, data={data!r})'. If the Table object does not have headers, it only includes the data in the string: '{type name}({data!r})'.

:param self: Table. An instance of the Table class.
:return: String. The string representation of the Table object.
"""
if self.headers:
    return '{type name}(headers={headers!r}, data={data!r})'.format(type=type(self).__name__, headers=self.headers, data=self.data)
else:
    return '{type name}({data!r})'.format(type=type(self).__name__, data=self.data)

"""This function renders a check constraint in a specific format. It first tries to render the constraint using a user-defined rendering function. If that fails, it checks if the constraint is part of a parent type already present in the table. If it is, it returns None. Otherwise, it constructs a string representation of the check constraint with optional parameters.

:param constraint: CheckConstraint. The check constraint to render.
:param autogen_context: AutogenContext. The autogen context.
:param namespace_metadata: Optional[MetaData]. The metadata of the namespace.
:return: Optional[str]. The rendered check constraint string, or None if the constraint is part of a parent type.
"""

if constraint.name is None:
    raise ValueError(
        "CheckConstraint must have a name: %r" % constraint
    )

if namespace_metadata is not None:
    # check if this is part of a parent type
    if (
        namespace_metadata.tables
        and constraint.table.name in namespace_metadata.tables
    ):
        t = namespace_metadata.tables[constraint.table.name]
        if t is not None and constraint.name in t.constraints:
            return None

if autogen_context.opts.get("template_args", {}).get("render_check_constraint"):
    render_fn = autogen_context.opts["render_check_constraint"]
    rendered = render_fn(
        constraint, autogen_context.dialect, autogen_context.opts
    )
    if rendered is not None:
        return rendered

rendered = constraint.sqltext.compile(
    dialect=autogen_context.dialect,
    compile_kwargs={"literal_binds": True},
)
return "CHECK (%s)" % render

"""Deserialize a value into a date instance. It first calls the parent class's deserialize method to convert the value into a date object. Then, it checks if the value is already None or an instance of allowed type in DateField class. If so, it returns the value as is. Otherwise, it converts the value into a string, and parse the string value into a datetime object and creates a new date object using the year, month, and day attributes of the datetime object.

:param cls: Class. The DateField class.
:param value: Object. The value to be deserialized into a DateField instance.
:param args: Object. Additional positional arguments.
:param kwargs: Object. Additional keyword arguments.
:return: date. The deserialized date instance.
"""
if value is None or isinstance(value, cls.allowed_type):
    return value
elif isinstance(value, str):
    return cls.allowed_type.fromisoformat(value)
else:
    raise TypeError(f"Cannot deserialize object of type {type(value)} into a date object.")

