:param value: The pair of values to be serialized.
:param display: Bool. Whether to display the serialized values. Defaults to False.
:return: String. The serialized representation of the pair.
"""
if value is None:
    return None
if not display and self.optional and value[0] == value[1]:
    return self.subtypes[0].serialize(value[0])
return '{} {}'.format(self.subtypes[0].serialize(value[0]), self.subtypes[1].serialize(value[1]))

